// n8n Code — Detecta URL de Maps en cualquier formato, obtiene lat/lon si es posible,
// o marca "needs_expand" cuando es un short link (maps.app.goo.gl / goo.gl) para expandirlo con HTTP Request.

// -------- utilidades --------
function extraerUrlMaps(str = "") {
  const re = /(https?:\/\/(?:www\.)?(?:google\.com\/maps|maps\.google\.com|goo\.gl\/maps|maps\.app\.goo\.gl)[^\s]*)/i;
  const m = String(str).match(re);
  return m ? m[1].trim() : null;
}
function norm(u){ return u ? u.replace(/\s+/g,"").trim() : null; }

// Patrones de coordenadas en URLs y texto final de Google Maps
function parseCoords(s = "") {
  if (!s) return null;
  const dec = decodeURIComponent(s);

  const pats = [
    /[?&]q=(-?\d+\.\d+),\s*(-?\d+\.\d+)/i,     // ?q=lat,lon
    /\/@(-?\d+\.\d+),\s*(-?\d+\.\d+)/i,        // /@lat,lon
    /[?&]center=(-?\d+\.\d+),\s*(-?\d+\.\d+)/i,// center=lat,lon
    /[?&]ll=(-?\d+\.\d+),\s*(-?\d+\.\d+)/i,    // ll=lat,lon
    /!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/i,         // ...!3dLAT!4dLON...
    /(^|[^-\d])(-?\d+\.\d+),\s*(-?\d+\.\d+)([^-\d]|$)/ // coords sueltas
  ];
  for (const rx of pats) {
    const m = dec.match(rx);
    if (m) {
      const lat = parseFloat(m[1] ?? m[2]);
      const lon = parseFloat(m[2] ?? m[3]);
      if (isFinite(lat) && isFinite(lon)) return { lat, lon };
    }
  }
  return null;
}

function haversineKm(a,b){
  const R=6371, toRad=d=>d*Math.PI/180;
  const dLat=toRad(b.lat-a.lat), dLon=toRad(b.lon-a.lon);
  const x=Math.sin(dLat/2)**2 + Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLon/2)**2;
  return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));
}

