// --- Función para extraer coordenadas desde una URL de Google Maps ---
function extraerCoordenadas(url) {
  if (typeof url !== "string" || !url.trim()) return null;
  const regex = /@(-?\d+\.\d+),(-?\d+\.\d+)/;      // formato con @lat,lon
  const regexQ = /[?&]q=(-?\d+\.\d+),(-?\d+\.\d+)/; // formato con ?q=lat,lon
  const match = url.match(regex) || url.match(regexQ);
  if (match) return { lat: parseFloat(match[1]), lon: parseFloat(match[2]) };
  return null; // si es URL corta sin coordenadas
}

// --- Función Haversine para distancia en km ---
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371; // km
  const toRad = deg => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

