// --- Función: extraer coordenadas de una URL de Google Maps ---
async function extraerCoordenadas(url) {
  if (typeof url !== "string" || !url.trim()) return null;

  // formatos conocidos: @lat,lon o ?q=lat,lon
  const regexAt = /@(-?\d+\.\d+),(-?\d+\.\d+)/;
  const regexQ = /[?&]q=(-?\d+\.\d+),(-?\d+\.\d+)/;

  let match = url.match(regexAt) || url.match(regexQ);
  if (match) return { lat: parseFloat(match[1]), lon: parseFloat(match[2]) };

  // si es URL corta (maps.app.goo.gl o goo.gl/maps)
  if (url.includes("goo.gl") || url.includes("maps.app.goo.gl")) {
    try {
      const res = await fetch(url, { method: "HEAD", redirect: "follow" });
      const finalUrl = res.url;
      match = finalUrl.match(regexAt) || finalUrl.match(regexQ);
      if (match) return { lat: parseFloat(match[1]), lon: parseFloat(match[2]) };
    } catch (e) {
      return null;
    }
  }
  return null;
}

// --- Haversine: distancia entre dos coordenadas (km) ---
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const toRad = d => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

