// n8n Code Node: Obtiene coordenadas (lat, lng) desde URLs de Google Maps
// Entrada: items[0].json["UBICACIÓN GOOGLE MAPS"] = [ "https://maps.app.goo.gl/...", ... ]

import fetch from 'node-fetch';

const apiKey = "AIzaSyBpq-8gHezszMmwTIySDLhd8VvnjHpjbWo"; // Coloca aquí tu API key
const urls = items[0].json["UBICACIÓN GOOGLE MAPS"];
const regex = /(https?:\/\/(?:www\.)?(?:goo\.gl|maps\.app\.goo\.gl|google\.com\/maps)[^\s]*)/i;
const base = "https://maps.googleapis.com/maps/api/geocode/json?address=";

const resultados = [];

for (const url of urls) {
	if (!url) continue;
	const match = url.match(regex);
	if (!match) continue;

	try {
		const response = await fetch(base + encodeURIComponent(url) + "&key=" + apiKey);
		const data = await response.json();

		if (data.results && data.results[0]) {
			const loc = data.results[0].geometry.location;
			resultados.push({
				json: {
					url_original: url,
					lat: loc.lat,
					lng: loc.lng
				}
			});
		} else {
			resultados.push({
				json: {
					url_original: url,
					error: "No se encontraron coordenadas"
				}
			});
		}
	} catch (err) {
		resultados.push({
			json: {
				url_original: url,
				error: err.message
			}
		});
	}
}

return resultados;
/**

**Configuración recomendada**
- Nodo: **Code (JavaScript)**  
- Modo: `Run Once for All Items`  
- Entrada: nodo `Aggregate` con campo `"UBICACIÓN GOOGLE MAPS"`  
- Salida: array con `{ url_original, lat, lng }`  

**Mitigaciones**
- Si Google limita peticiones, usa un nodo `Wait` de 200 ms entre iteraciones.  
- Si URLs son acortadas (maps.app.goo.gl), puedes expandirlas antes con un nodo `HTTP Request` (`GET` sin seguir redirecciones).

 * 
 */

const url = $input.item.json.url;

async function resolveUrl(shortUrl) {
  try {
    const response = await fetch(shortUrl, {
      method: 'HEAD',
      redirect: 'follow'
    });
    return response.url;
  } catch (error) {
    return shortUrl;
  }
}

let resolvedUrl = url;
if (url.includes('goo.gl') || url.includes('maps.app.goo.gl')) {
  resolvedUrl = await resolveUrl(url);
}

const placeIdMatch = resolvedUrl.match(/maps\/place\/[^\/]+\/data=.*!3d(-?[\d.]+)!4d(-?[\d.]+)/);
const coordsMatch = resolvedUrl.match(/@(-?[\d.]+),(-?[\d.]+)/);
const qMatch = resolvedUrl.match(/[?&]q=(-?[\d.]+),(-?[\d.]+)/);

let latitude = null;
let longitude = null;

if (coordsMatch) {
  latitude = parseFloat(coordsMatch[1]);
  longitude = parseFloat(coordsMatch[2]);
} else if (qMatch) {
  latitude = parseFloat(qMatch[1]);
  longitude = parseFloat(qMatch[2]);
} else if (placeIdMatch) {
  latitude = parseFloat(placeIdMatch[1]);
  longitude = parseFloat(placeIdMatch[2]);
}

return {
  originalUrl: url,
  resolvedUrl: resolvedUrl,
  latitude: latitude,
  longitude: longitude
};
